<script lang="ts">import Icon from './Icon.svelte';export let status:string;const icons:Record<string,string>={'Draft':'claim','Submitted':'clock','Manager approved':'check','Finance approved':'check','Paid':'check','Rejected':'close','Returned for correction':'return','Cancelled':'close','Block':'close','Warn':'warning','Info':'info'};$: tone=['Paid','Manager approved','Finance approved'].includes(status)?'success':['Rejected','Block'].includes(status)?'danger':['Returned for correction','Warn'].includes(status)?'warning':status==='Submitted'||status==='Info'?'brand':'neutral';</script>
<span class="status {tone}"><Icon name={icons[status]||'info'} size={13}/>{status}</span>